import ast
src=open('/workspace/submission/main.py').read()
tree=ast.parse(src)
names=[n.id for n in ast.walk(tree) if isinstance(n,ast.Name)]
defined={n.name for n in ast.walk(tree) if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
assigned=set()
for n in ast.walk(tree):
    if isinstance(n,ast.Assign):
        for t in n.targets:
            if isinstance(t,ast.Name): assigned.add(t.id)
    if isinstance(n,(ast.Import,ast.ImportFrom)):
        for a in n.names: assigned.add((a.asname or a.name).split('.')[0])
unused = sorted(x for x in (defined|assigned) if names.count(x)==0 and x not in ('main','run'))
print('possibly unused:', unused)
print('imports:', [n.names[0].name for n in ast.walk(tree) if isinstance(n,ast.Import)])
print('size', len(src.encode()), 'lines', src.count(chr(10)))
EOF
